import{_ as t,o,c as r,a5 as s}from"./chunks/framework.DJo0M80U.js";const g=JSON.parse('{"title":"手写一个支持 import-export 的 ESM 加载器","description":"好，我们来进入推荐的第二章 —— 手写一个支持 import/export 的 ESM 加载器（简化版） 。这也是构建现代模块打包器（如 Vite、Webpack）的核心基础。 第二章：手写一个简易版 ESModule 加载器 模拟构建一个支持 import / export 的。","frontmatter":{"title":"手写一个支持 import-export 的 ESM 加载器","date":"2026-08-11T00:00:00.000Z","categories":["JavaScript 系统教程"],"tags":["JavaScript","前端","教程","OneNote","模块化与工程化"],"description":"好，我们来进入推荐的第二章 —— 手写一个支持 import/export 的 ESM 加载器（简化版） 。这也是构建现代模块打包器（如 Vite、Webpack）的核心基础。 第二章：手写一个简易版 ESModule 加载器 模拟构建一个支持 import / export 的。","sidebarWeight":40,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/b-原生js/12-模块化编程/实现esmodule/手写一个支持 import-export 的 ESM 加载器.md"},"headers":[],"relativePath":"posts/JavaScript系统教程/06-模块化与工程化/实现esmodule/手写一个支持 import-export 的 ESM 加载器.md","filePath":"posts/JavaScript系统教程/06-模块化与工程化/实现esmodule/手写一个支持 import-export 的 ESM 加载器.md"}'),a={name:"posts/JavaScript系统教程/06-模块化与工程化/实现esmodule/手写一个支持 import-export 的 ESM 加载器.md"};function p(n,e,i,m,l,c){return o(),r("div",null,[...e[0]||(e[0]=[s('<div><h1 id="手写一个支持-import-export-的-esm-加载器" tabindex="-1">手写一个支持 import-export 的 ESM 加载器 <a class="header-anchor" href="#手写一个支持-import-export-的-esm-加载器" aria-label="Permalink to &quot;手写一个支持 import-export 的 ESM 加载器&quot;">​</a></h1><blockquote><p>本节目标：理解“手写一个支持 import-export 的 ESM 加载器”的核心思路，并能把它用于实际开发或面试表达。 好，我们来进入推荐的第二章 —— <strong>手写一个支持 import/export 的 ESM 加载器（简化版）</strong>。这也是构建现代模块打包器（如 Vite、Webpack）的核心基础。</p></blockquote><p><strong>第二章：手写一个简易版 ESModule 加载器</strong> 模拟构建一个支持 import / export 的模块系统，包括：</p><ul><li>静态分析依赖（构建模块图）</li><li>模拟 live binding（实时绑定）</li><li>控制模块的加载顺序</li></ul><p><strong>一、准备项目结构</strong> esloader/├── main.js // 启动程序├── loader.js // 核心模块加载器├── a.mjs // 模拟模块 A└── b.mjs // 模拟模块 B</p><p><strong>二、创建 a.mjs</strong> export const msg = &#39;Hello from A&#39;; setTimeout(() =&gt; { console.log(&#39;A 修改 msg&#39;); exports.msg = &#39;Updated from A&#39;;}, 1000); <strong>三、创建 b.mjs</strong> import { msg } from &#39;./a.mjs&#39;; console.log(&#39;B 读取 A 的 msg：&#39;, msg); setTimeout(() =&gt; { console.log(&#39;B 再次读取 A 的 msg：&#39;, msg);}, 2000); 注意：我们为了简化不考虑 ESM 中不能修改 export 的限制，用了 exports.msg = ... 做模拟。</p><p><strong>四、loader.js — 编写加载器</strong> const fs = require(&#39;fs&#39;);const path = require(&#39;path&#39;); // 模拟模块图缓存const moduleGraph = new Map(); async function loadModule(filePath) { const absPath = path.resolve(__dirname, filePath); if (moduleGraph.has(absPath)) { return moduleGraph.get(absPath).namespace; } const code = fs.readFileSync(absPath, &#39;utf-8&#39;); // 提取 import/export，构建依赖图（简单正则模拟） const importRegex = /import\\s+{?([\\w\\s,]*)}?\\s+from\\s+<a href="./.+">&#39;&quot;</a>[&#39;&quot;]/g; const exportRegex = /export\\s+(const|let|var)\\s+(\\w+)/g; const dependencies = []; let match; while ((match = importRegex.exec(code))) { const [, imports, depPath] = match; dependencies.push({ imports, depPath }); } // 创建模块 namespace（模拟实时绑定） const namespace = {}; moduleGraph.set(absPath, { namespace }); // 递归加载依赖模块 for (const dep of dependencies) { const depNamespace = await loadModule(dep.depPath); const names = dep.imports.split(&#39;,&#39;).map(s =&gt; s.trim()); // 建立 live binding（引用） for (const name of names) { Object.defineProperty(namespace, name, { enumerable: true, get: () =&gt; depNamespace[name] }); } } // 用 Function 执行模块代码，模拟执行环境 const wrappedCode = code .replace(importRegex, &#39;&#39;) // 移除 import .replace(exportRegex, &#39;namespace.$2 =&#39;); // 模拟 export const fn = new Function(&#39;namespace&#39;, &#39;exports&#39;, wrappedCode); fn(namespace, namespace); // 传入命名空间对象 return namespace;} module.exports = { loadModule };</p><p><strong>五、main.js</strong> const { loadModule } = require(&#39;./loader&#39;); (async () =&gt; { await loadModule(&#39;./b.mjs&#39;);})();</p><p><strong>运行结果</strong> $ node main.jsB 读取 A 的 msg： Hello from AA 修改 msgB 再次读取 A 的 msg： Updated from A</p><p><strong>重点实现说明：</strong></p><ul><li><strong>静态分析依赖关系</strong>： 用正则提取 import/export 模拟了编译阶段的依赖图构建。</li><li><strong>模块缓存</strong>： 用 Map 缓存每个模块，避免重复加载。</li><li><strong>live binding 模拟</strong>： 用 Object.defineProperty 模拟 ESM 的实时绑定特性。</li><li><strong>执行环境</strong>： 用 new Function + namespace 参数作为作用域，动态执行模块。</li></ul><p><strong>下一章计划（第三章）</strong> 如果你还想继续深入，我们可以做：</p><ul><li><strong>支持默认导出 export default</strong></li><li><strong>用 AST（如 acorn）替代正则做 import/export 解析</strong></li><li><strong>支持 top-level await 模块的异步加载</strong></li><li><strong>打包工具原型：将多个模块打包为一个文件</strong></li></ul><p>你想继续深入哪一块？我可以把后续也拆成教程继续写下去。 &gt; 来自 &lt;<a href="https://chatgpt.com/c/6805aef6-e7b4-8004-ab43-9a137f666985" target="_blank" rel="noreferrer">https://chatgpt.com/c/6805aef6-e7b4-8004-ab43-9a137f666985</a>&gt;</p></div>',1)])])}const u=t(a,[["render",p]]);export{g as __pageData,u as default};
